on conflict (key) do nothing;
update game_config set value = jsonb_set(value, '{areas}', '{"c3da0041-6de3-5997-8243-ab9b3559f166":[{"dex":425,"tier":"rare"},{"dex":92,"tier":"veryRare"}],"be8feb03-b0a9-57e8-b720-8efb8158be5f":[{"dex":92,"tier":"common"},{"dex":622,"tier":"rare"}],"6bf5cdc8-d9a0-5222-867a-a9b955f0d3d2":[{"dex":708,"tier":"common"},{"dex":710,"tier":"common"},{"dex":946,"tier":"common"}],"45c379ef-71bc-58cc-a268-a59aaf818f6f":[{"dex":607,"tier":"common"},{"dex":353,"tier":"common"},{"dex":200,"tier":"veryRare"}],"8a531ee2-3eae-5340-89e5-489e482f0728":[{"dex":622,"tier":"common"}],"baf5ef53-0f38-53ca-841b-38f81e77cc54":[{"dex":353,"tier":"common"},{"dex":355,"tier":"common"},{"dex":478,"tier":"veryRare"}],"4b5f0177-dcfe-5760-99c1-57b26089f2be":[{"dex":769,"tier":"common"}],"a83d3d74-c03b-5d9c-9e72-0be42242b332":[{"dex":679,"tier":"common"},{"dex":680,"tier":"veryRare"}],"974c4771-faf0-5c54-a203-14cac004d652":[{"dex":425,"tier":"common"},{"dex":426,"tier":"rare"},{"dex":947,"tier":"rare"}],"19d09269-ac38-5bd3-bad9-cafbb9a9d9c4":[{"dex":355,"tier":"common"},{"dex":200,"tier":"common"},{"dex":354,"tier":"common"},{"dex":356,"tier":"rare"}]}'::jsonb
  || case when jsonb_typeof(value -> 'areas') = 'object' then value -> 'areas' else '{}'::jsonb end)
