-- ---------------------------------------------------------------- 2. the switches

create or replace function power_open(p_kind text)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(a = 'all' or (a = 'admin' and is_admin()), false)
  from (
    select case p_kind
      when 'mega' then (select value -> 'gems' ->> 'access' from game_config
                        where key = 'megaEvolution' and jsonb_typeof(value) = 'object')
      when 'gmax' then (select value -> 'boost' ->> 'access' from game_config
                        where key = 'gigantamax' and jsonb_typeof(value) = 'object')
      when 'z' then (select value ->> 'access' from game_config where key = 'zMove' and jsonb_typeof(value) = 'object')
    end a
  ) x
$$;
revoke all on function power_open(text) from public;
grant execute on function power_open(text) to anon, authenticated;

-- ---------------------------------------------------------------- 3. a player's powers

-- From the save of that realm: `powers.gems` (strings only) and `powers.earned` (the badges won). Every key always
-- there, so the game reads one shape; a switch off for the caller empties its part.
create or replace function player_powers(p_user uuid, p_realm text default 'main')
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'gems', case when power_open('mega') then coalesce((
              select jsonb_agg(g) from jsonb_array_elements(
                case when jsonb_typeof(p -> 'gems') = 'array' then p -> 'gems' else '[]'::jsonb end
              ) g where jsonb_typeof(g) = 'string'
            ), '[]'::jsonb) else '[]'::jsonb end,
    'gmax', power_open('gmax') and coalesce(jsonb_typeof(p -> 'earned') = 'array' and p -> 'earned' ? 'gmax', false),
    'z', power_open('z') and coalesce(jsonb_typeof(p -> 'earned') = 'array' and p -> 'earned' ? 'z', false)
  )
  from (
    select coalesce((select s.data -> 'powers' from saves s where s.user_id = p_user and s.realm = p_realm), '{}'::jsonb) p
  ) x
$$;
revoke all on function player_powers(uuid, text) from public;

-- ---------------------------------------------------------------- 4. the Versus board

-- 0049's, with the powers. Versus (0018) is optional on a database that only ran seed.sql: made only when its tables
-- are there.
drop function if exists versus_board(text);
do $do$
begin
  if to_regclass('public.versus_teams') is null then
    return;
  end if;
  execute $ddl$
    create or replace function versus_board(p_realm text default 'main')
    returns table (
      user_id uuid,
      is_me boolean,
      name text,
      "character" text,
      team jsonb,
      ids jsonb,
      version int,
      attack_wins int,
      defense_wins int,
      beaten boolean,
      rich boolean,
      powers jsonb
    )
    language sql stable security definer set search_path = public as $body$
      select
        v.user_id,
        v.user_id = auth.uid(),
        coalesce(c.name, 'Trainer'),
        coalesce(c.avatar, 'red'),
        v.team,
        case when v.user_id = auth.uid() then v.ids end,
        v.version,
        (select count(*)::int from versus_battles b where b.realm = v.realm and b.attacker_id = v.user_id and b.won),
        (
          select count(*)::int from (
            select distinct b.attacker_id, b.defender_version from versus_battles b
            where b.realm = v.realm and b.defender_id = v.user_id and not b.won
          ) held
        ),
        exists (
          select 1 from versus_battles b
          where b.realm = v.realm and b.attacker_id = auth.uid() and b.defender_id = v.user_id
            and b.defender_version = v.version and b.won
        ),
        player_rich(v.user_id),
        player_powers(v.user_id, v.realm)
      from versus_teams v
      left join player_cards c on c.user_id = v.user_id and c.realm = v.realm
      where v.realm = p_realm
      order by v.updated_at desc
      limit 1000
    $body$
  $ddl$;
  revoke all on function versus_board(text) from public;
  grant execute on function versus_board(text) to anon, authenticated;
end
$do$;

-- ↓ supabase/migrations/0065_raid_true_levels.sql, inlined so this file stands alone.
-- Raid teams at their own levels (the user's rule, 2026-10-18): a Pokémon fights at a raid's team cap, but its dice
-- and rerolls stay those of its own level. The game caps it in the fight (`raidSeedLevels`), so the teams
-- registered for friends keep each Pokémon's real level instead of `least(level, cap)`. Still built from the cloud
-- save, never from what the page sends. Run after 0064; safe to run again. A team registered before keeps its capped
-- levels until its owner registers it again (choosing it, or starting a raid with it).

-- 0039's, the level no longer capped.
create or replace function raid_set_team(p_ids text[], p_realm text default 'main')
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  save jsonb;
  new_team jsonb;
begin
  if me is null then raise exception 'events_signed_out'; end if;
  if p_ids is null or coalesce(array_length(p_ids, 1), 0) not between 1 and 3
     or (select count(distinct x) from unnest(p_ids) x) <> array_length(p_ids, 1) then
    raise exception 'events_team_size';
  end if;
  select s.data into save from saves s where s.user_id = me and s.realm = p_realm;
  if save is null then raise exception 'events_no_save'; end if;
  select jsonb_agg(jsonb_build_object(
    'dex', (m ->> 'dex')::int,
    'level', least(100, greatest(1, (m ->> 'level')::int)),
    'shiny', coalesce((m ->> 'shiny')::boolean, false)
  ) order by t.ord)
  into new_team
  from unnest(p_ids) with ordinality t(id, ord)
  join (
    select b from jsonb_array_elements(coalesce(save -> 'box', '[]')) b
    union all
    select b from jsonb_each(coalesce(save -> 'parked', '{}')) p(k, v), jsonb_array_elements(coalesce(p.v -> 'box', '[]')) b
  ) boxes(m) on m ->> 'id' = t.id
  where m ->> 'revivesAt' is null;
  if new_team is null or jsonb_array_length(new_team) <> array_length(p_ids, 1) then raise exception 'events_not_eligible'; end if;
  insert into raid_teams (user_id, realm, team, ids, updated_at) values (me, p_realm, new_team, to_jsonb(p_ids), now())
  on conflict (user_id, realm) do update set team = excluded.team, ids = excluded.ids, updated_at = now();
  return new_team;
end $$;

-- 0060's, the level no longer capped (a portal or nightmare raid's checks kept as they are).
create or replace function raid_progress_set_team(p_key text, p_region text, p_ids text[], p_realm text default 'main')
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  dex int := raid_progress_dex(p_key);
  region text := (select a.region_id from areas a where a.id::text = split_part(p_key, ':', 1));
  save jsonb;
  box jsonb;
  new_team jsonb;
begin
  if me is null then raise exception 'events_signed_out'; end if;
  if dex is null or region is null then raise exception 'events_bad_raid'; end if;
  if p_ids is null or coalesce(array_length(p_ids, 1), 0) not between 1 and 3
     or (select count(distinct x) from unnest(p_ids) x) <> array_length(p_ids, 1) then
    raise exception 'events_team_size';
  end if;
  select s.data into save from saves s where s.user_id = me and s.realm = p_realm;
  if save is null then raise exception 'events_no_save'; end if;
  if raid_progress_special_locked(p_key, p_realm) then raise exception 'events_raid_locked'; end if;
  -- The Box being played is the save's top-level one (a small world's while inside it); the others are parked.
  box := case when coalesce(save ->> 'region', 'kanto') = region then save -> 'box' else save -> 'parked' -> region -> 'box' end;
  select jsonb_agg(jsonb_build_object(
    'dex', (m ->> 'dex')::int,
    'level', least(100, greatest(1, (m ->> 'level')::int)),
    'shiny', coalesce((m ->> 'shiny')::boolean, false)
  ) order by t.ord)
  into new_team
  from unnest(p_ids) with ordinality t(id, ord)
  join jsonb_array_elements(coalesce(box, '[]')) m on m ->> 'id' = t.id
  where m ->> 'revivesAt' is null;
  if new_team is null or jsonb_array_length(new_team) <> array_length(p_ids, 1) then raise exception 'events_not_eligible'; end if;
  insert into raid_progress_teams (user_id, realm, raid_key, region, team, ids, updated_at)
  values (me, p_realm, p_key, region, new_team, to_jsonb(p_ids), now())
  on conflict (user_id, realm, raid_key) do update
    set region = excluded.region, team = excluded.team, ids = excluded.ids, updated_at = now();
  return new_team;
end $$;


-- ↓ supabase/migrations/0066_leaderboard_worlds.sql, inlined so this file stands alone.
-- Small worlds get a leaderboard (the user's ask of 2026-10-18). A world has no gyms, so 0024's rule (a region's row
-- only once its player holds a badge there) left every world board empty. In a world, the first area cleared stands
-- for the badge: every trainer who has cleared one of its areas is on its board, badges elsewhere or not.
--
-- A world is a region on the admin's list (game_config `smallWorlds`, as trade_world() in 0044 reads it), so a world
-- taken off the list leaves the boards with it. Everything else is 0054's leaderboard(), the same columns and order;
-- the same signature and return type, so `create or replace` keeps its grants. Run after 0054. seed.sql inlines it
-- after 0064. Safe to run again.

create or replace function leaderboard(p_realm text default 'main')
returns table (
  region text,
  is_me boolean,
  name text,
  "character" text,
  team jsonb,
  pokedex int,
  max_level int,
  shinies int,
  progress jsonb,
  is_friend boolean,
  friend_id uuid,
  raids_won int,
  rich boolean,
  lead boolean,
  shinies_all int
)
language sql stable security definer set search_path = public as $$
  select r.region, r.user_id = auth.uid(), c.name, c.avatar, r.team, r.pokedex, r.max_level, r.shinies, r.progress,
         m.id is not null, m.id, coalesce(e.raids_won, 0), player_rich(c.user_id),
         row_number() over (partition by r.user_id order by r.region = c.region desc, r.region) = 1,
         (
           select coalesce(sum(a.shinies), 0)::int from player_card_regions a
           where a.user_id = r.user_id and a.realm = r.realm
         )
  from player_card_regions r
  join player_cards c on c.user_id = r.user_id and c.realm = r.realm
  left join friend_ids_of(auth.uid()) m on m.id = r.user_id
  left join event_state e on e.user_id = r.user_id and e.realm = r.realm
  where r.realm = p_realm
    and (
      cardinality(r.badges) > 0
      or (
        exists (
          select 1
          from jsonb_array_elements(coalesce((select value -> 'list' from game_config where key = 'smallWorlds'), '[]')) w
          where w ->> 'regionId' = r.region
        )
        and exists (select 1 from jsonb_each(r.progress) p(k, v) where coalesce((v ->> 'cleared')::boolean, false))
      )
    )
    and (c.updated_at > now() - interval '72 hours' or r.user_id = auth.uid())
    and not exists (select 1 from leaderboard_bans x where x.user_id = r.user_id)
  order by c.updated_at desc, r.user_id
  limit 3000
$$;

revoke all on function leaderboard(text) from public;
grant execute on function leaderboard(text) to anon, authenticated;

