-- ↓ supabase/migrations/0071_kofi.sql, inlined so this file stands alone.
-- Ko-fi replaces PayPal for "Support me" (docs/23 §11): the game's button leads to Ko-fi, Ko-fi tells the site about
-- each payment (netlify/functions/kofi-webhook.mts), and a weekly Discord post in #support-me reads the month's totals.
--
-- 1. game_config `donation`: the Ko-fi link replaces the PayPal one, and the weekly post's goal (0 = none) and
--    currency join it, kept equal to the game's defaults. An admin's own Ko-fi link, goal or currency is left alone.
-- 2. kofi_payments: one row per Ko-fi payment (a one-off donation, a membership's month, a shop order or a commission).
--    No e-mail is kept: a membership's months are tied together by a hash of it. Only the webhook (service role)
--    writes it; the admin can read it.
-- 3. kofi_totals: what the weekly post shows, per currency: this month's total and supporters, and what next month
--    already holds (each membership paid within 35 days, as it renews). Totals only, so anyone may ask.
-- 4. configVersion + 1, so players fetch the new link. Safe to run again.

-- ---------------------------------------------------------------- 1. the link

update game_config
set value = (value - 'paypalUrl') || '{"kofiUrl": "https://ko-fi.com/gregoirefontaine"}'::jsonb
where key = 'donation' and jsonb_typeof(value) = 'object' and not value ? 'kofiUrl';
update game_config set value = '{"monthlyGoal": 0, "currency": "EUR"}'::jsonb || value
where key = 'donation' and jsonb_typeof(value) = 'object';

-- ---------------------------------------------------------------- 2. the payments

create table if not exists kofi_payments (
  transaction_id text primary key,
  -- Ko-fi's type: Donation, Subscription, Commission or Shop Order.
  kind text not null,
  amount numeric(12, 2) not null check (amount >= 0),
  currency text not null,
  paid_at timestamptz not null,
  -- A membership's monthly payment (the first one included).
  subscription boolean not null default false,
  -- sha256 of the supporter's e-mail, lowercased: the same member month after month, never the address.
  supporter text,
  tier text,
  received_at timestamptz not null default now()
);
create index if not exists kofi_payments_paid_at on kofi_payments (paid_at);

alter table kofi_payments enable row level security;
revoke all on kofi_payments from anon, authenticated;
grant select on kofi_payments to authenticated;
drop policy if exists kofi_payments_admin_read on kofi_payments;
create policy kofi_payments_admin_read on kofi_payments for select using (is_admin());

-- ---------------------------------------------------------------- 3. the totals

create or replace function kofi_totals(p_now timestamptz default now())
returns table (currency text, this_month numeric, supporters int, next_month numeric)
language sql stable security definer set search_path = public as $$
  with bounds as (
    select date_trunc('month', p_now at time zone 'utc') at time zone 'utc' as start
  ),
  month_paid as (
    select k.currency, sum(k.amount) as total, count(distinct coalesce(k.supporter, k.transaction_id))::int as n
    from kofi_payments k, bounds b
    where k.paid_at >= b.start and k.paid_at < b.start + interval '1 month' and k.paid_at <= p_now
    group by k.currency
  ),
  -- Each membership's latest month: paid within 35 days, it renews next month (Ko-fi says nothing of a cancelled one,
  -- so a missed renewal drops it after 35 days).
  members as (
    select distinct on (k.supporter) k.currency, k.amount, k.paid_at
    from kofi_payments k
    where k.subscription and k.supporter is not null and k.paid_at <= p_now
    order by k.supporter, k.paid_at desc
  ),
  renewing as (
    select m.currency, sum(m.amount) as total from members m where m.paid_at > p_now - interval '35 days' group by m.currency
  )
  select coalesce(p.currency, r.currency), coalesce(p.total, 0), coalesce(p.n, 0), coalesce(r.total, 0)
  from month_paid p
  full join renewing r on r.currency = p.currency
  order by 2 desc
$$;
grant execute on function kofi_totals(timestamptz) to anon, authenticated;

-- ---------------------------------------------------------------- 4. players fetch the change

insert into game_config (key, value) values ('configVersion', '1'::jsonb) on conflict (key) do update set value = to_jsonb(coalesce((game_config.value #>> '{}')::int, 0) + 1);

-- ↓ supabase/migrations/0072_live_recurring.sql, inlined so this file stands alone.
-- Live events that come back, and live events that overlap (docs/20 §9). A live event runs once (its `start` and
-- `end`) or comes back by itself (`repeat`): every year on a date, or on a weekday, every week or on some weeks of the
-- month, at a time (UTC) for some hours. Each run is an event of its own, `<id>@<YYYY-MM-DD>` (the UTC date it starts),
-- so the Underground's teams, kits and orbs start afresh each time, as they do between two one-off events. "End now"
-- on a recurring event ends one run only (`stops`: the run's date → when it ended).
--
-- 1. live_run_at(e, t): the run of one event that is on at `t` (its id and start), the engine's liveRuns
--    (src/engine/liveEvents.ts; tests/live-recurring-sql.test.ts keeps the two the same).
-- 2. ug_live(): 0063's, through it. Events may overlap now, except two Undergrounds (the admin refuses them); should
--    two be on anyway, the earliest started is the one, as in the game.
--
-- Run after 0063; safe to run again. seed.sql inlines it (scripts/seed.ts), after 0070.

-- ---------------------------------------------------------------- 1. a run on at a moment

create or replace function live_run_at(e jsonb, t timestamptz)
returns table (run text, starts timestamptz)
language plpgsql stable set search_path = public as $$
declare
  r jsonb := e -> 'repeat';
  kind text := r ->> 'kind';
  hours numeric;
  len interval;
  tod interval;
  d date;
  key text;
  s timestamptz;
  en timestamptz;
  stop timestamptz;
  ok boolean;
begin
  -- Once: between its start (included) and its end (excluded).
  if jsonb_typeof(r) is distinct from 'object' or kind is null or kind not in ('yearly', 'weekly') then
    if (e ->> 'start')::timestamptz <= t and t < (e ->> 'end')::timestamptz then
      run := e ->> 'id';
      starts := (e ->> 'start')::timestamptz;
      return next;
    end if;
    return;
  end if;
  -- At least an hour; a weekly run never reaches the next week's, a yearly one lasts a month at most.
  hours := case when coalesce(r ->> 'hours', '') ~ '^[0-9]+(\.[0-9]+)?$' and (r ->> 'hours')::numeric > 0 then (r ->> 'hours')::numeric else 24 end;
  len := interval '1 hour' * least(case kind when 'weekly' then 168 else 744 end, greatest(1, hours));
  tod := case when coalesce(r ->> 'time', '') ~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' then (r ->> 'time')::interval else interval '0' end;
  -- A run that started up to its length before `t` may still be on.
  for d in
    select g::date from generate_series(((t - len - tod) at time zone 'UTC')::date, (t at time zone 'UTC')::date, interval '1 day') g
  loop
    if kind = 'yearly' then
      ok := extract(month from d) = (r ->> 'month')::int and extract(day from d) = (r ->> 'day')::int;
    else
      ok := extract(dow from d) = (r ->> 'weekday')::int and (
        jsonb_typeof(r -> 'weeks') is distinct from 'array'
        or jsonb_array_length(r -> 'weeks') = 0
        or (r -> 'weeks') @> to_jsonb(ceil(extract(day from d) / 7.0)::int)
        or ((r -> 'weeks') @> '"last"'::jsonb and extract(month from d + 7) <> extract(month from d))
      );
    end if;
    if coalesce(ok, false) then
      key := to_char(d, 'YYYY-MM-DD');
      s := (d::timestamp + tod) at time zone 'UTC';
      en := s + len;
      stop := nullif(e -> 'stops' ->> key, '')::timestamptz;
      if stop is not null then
        en := greatest(s, least(en, stop));
      end if;
      if s <= t and t < en then
        run := (e ->> 'id') || '@' || key;
        starts := s;
        return next;
        return;
      end if;
    end if;
  end loop;
  return;
end $$;

-- ---------------------------------------------------------------- 2. the Underground running now

-- The id of the Underground live event's run on now (start included, end excluded), while the live events' switch and
-- the Underground's are on for the caller; null otherwise.
create or replace function ug_live()
returns text
language sql stable security definer set search_path = public as $$
  select x.run
  from game_config g,
    jsonb_array_elements(case when jsonb_typeof(g.value -> 'list') = 'array' then g.value -> 'list' else '[]'::jsonb end) e,
    lateral live_run_at(e, now()) x
  where g.key = 'liveEvents'
    and (g.value ->> 'access' = 'all' or (g.value ->> 'access' = 'admin' and is_admin()))
    and e ->> 'type' = 'underground'
    and ug_open()
  order by x.starts, x.run
  limit 1
$$;

revoke all on function live_run_at(jsonb, timestamptz) from public, anon, authenticated;
revoke all on function ug_live() from public, anon, authenticated;

-- ↓ supabase/migrations/0073_status_faces.sql, inlined so this file stands alone.
-- Status faces, reworked (docs/01 §3.2): a single face is enough for every status, so the thresholds are gone.
-- 1. game_config `status`: Poison 5 % for 5 turns; Freeze and Paralysis a chance per face (sure at 3 and at 2 faces);
--    Confusion 10 % recoil per face, 3 faces at most; Heal the Heal faces' value plus their die's upgrade (nothing to
